CREATE OR REPLACE FUNCTION public.create_owned_provider_operation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tid uuid; BEGIN IF NEW.provider_owned_operation AND NOT NEW.is_test AND NEW.trip_kind='passenger' AND NEW.transport_type<>'delivery' THEN tid:=public.promote_ride_request_to_trip(NEW.id); IF tid IS NULL THEN RAISE EXCEPTION 'Owned trip unavailable'; END IF; IF NEW.customer_quote_draft_id IS NOT NULL THEN UPDATE public.trip_drafts SET submitted_trip_id=tid WHERE id=NEW.customer_quote_draft_id AND user_id=NEW.actor_user_id AND submitted_trip_id IS NULL; END IF; END IF; RETURN NEW; END $$;
CREATE FUNCTION public.invoice_safe_events(_invoice uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN public.trip_invoice_access(_invoice,false) THEN (SELECT coalesce(jsonb_agg(jsonb_build_object('action',action,'created_at',created_at) ORDER BY created_at),'[]'::jsonb) FROM public.trip_invoice_events WHERE invoice_id=_invoice AND action IN ('invoice_ready','invoice_sent','invoice_viewed','payment_pending','payment_succeeded','payment_failed','refund_confirmed','reversal_confirmed')) ELSE '[]'::jsonb END $$;
REVOKE ALL ON FUNCTION public.invoice_safe_events(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.invoice_safe_events(uuid) TO authenticated;
CREATE FUNCTION public.checkout_acceptance_evidence_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user NOT IN ('postgres','service_role','supabase_admin') OR NEW.terms_version<>'2026-11-07' OR NEW.refund_version<>'2026-11-07' OR jsonb_typeof(NEW.review_snapshot)<>'object' OR NEW.attribution_hash !~ '^[a-f0-9]{64}$' OR NEW.review_snapshot->>'currency'<>'usd' OR (NEW.review_snapshot->>'amountCents')::bigint IS DISTINCT FROM NEW.amount_cents OR nullif(NEW.review_snapshot->>'payer','') IS NULL OR nullif(NEW.review_snapshot->>'merchant','') IS NULL OR jsonb_typeof(NEW.review_snapshot->'recurring')<>'boolean' OR jsonb_typeof(NEW.review_snapshot->'fees')<>'array' THEN RAISE EXCEPTION 'Authoritative complete purchase evidence required';END IF; IF NEW.reference_type IN ('customer_invoice','facility_invoice') AND (NEW.invoice_id IS NULL OR nullif(trim(NEW.provider_policy_snapshot->>'text'),'') IS NULL) THEN RAISE EXCEPTION 'Invoice provider policy snapshot required';END IF;RETURN NEW;END $$;
CREATE TRIGGER complete_acceptance_evidence BEFORE INSERT ON public.checkout_policy_acceptances FOR EACH ROW EXECUTE FUNCTION public.checkout_acceptance_evidence_guard();